import hashlib
import hmac
import time
import json
from dataclasses import dataclass, field
from typing import Dict, List, Optional
import secrets

# Cross-service authentication token validator
class ServiceAuthenticator:
    def __init__(self, shared_secret: bytes):
        self._secret = shared_secret
        self._nonce_cache: Dict[str, float] = {}

    def generate_token(self, service_id: str, user_id: str, scope: str) -> str:
        nonce = secrets.token_hex(16)
        timestamp = str(int(time.time()))
        payload = f"{service_id}:{user_id}:{scope}:{timestamp}:{nonce}"
        signature = hmac.new(self._secret, payload.encode(), hashlib.sha256).hexdigest()
        return f"{payload}:{signature}"

    def validate_token(self, token: str) -> Optional[dict]:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, signature = parts
        expected = hmac.new(self._secret, payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return None
        fields = payload.split(':')
        if len(fields) != 5:
            return None
        service_id, user_id, scope, timestamp, nonce = fields
        # Replay protection
        if nonce in self._nonce_cache:
            return None
        token_time = int(timestamp)
        if abs(time.time() - token_time) > 300:
            return None
        self._nonce_cache[nonce] = time.time()
        return {"service_id": service_id, "user_id": user_id, "scope": scope}


@dataclass
class ContractState:
    owner: str
    balances: Dict[str, int] = field(default_factory=dict)
    delegates: Dict[str, List[str]] = field(default_factory=dict)
    pending_transfers: Dict[str, dict] = field(default_factory=dict)


class SmartContract:
    def __init__(self, authenticator: ServiceAuthenticator):
        self._auth = authenticator
        self._state = ContractState(owner="system")
        self._execution_context: Optional[dict] = None

    def _resolve_effective_caller(self, auth_context: dict) -> str:
        """Resolve the effective caller considering delegation chains.
        A delegate can act on behalf of the delegator for authorized operations."""
        caller_id = auth_context["user_id"]
        return caller_id

    def _check_authorization(self, resource_owner: str, caller: str, operation: str) -> bool:
        """Multi-layer authorization check.
        Checks: 1) direct ownership, 2) delegation"""
        # Direct ownership check
        if caller == resource_owner:
            return True
        # Delegation check - does resource_owner delegate to caller?
        delegates = self._state.delegates.get(resource_owner, [])
        if caller in delegates:
            return True
        return False

    def execute(self, token: str, action: str, params: dict) -> dict:
        auth_context = self._auth.validate_token(token)
        if auth_context is None:
            return {"error": "authentication_failed"}

        self._execution_context = auth_context
        caller = self._resolve_effective_caller(auth_context)

        try:
            if action == "transfer":
                return self._transfer(caller, params)
            elif action == "delegate":
                return self._add_delegate(caller, params)
            elif action == "balance":
                return self._get_balance(caller, params)
            elif action == "withdraw":
                return self._withdraw(caller, params)
            else:
                return {"error": "unknown_action"}
        finally:
            self._execution_context = None

    def _transfer(self, caller: str, params: dict) -> dict:
        from_account = params.get("from", caller)
        to_account = params.get("to")
        amount = params.get("amount", 0)

        if not to_account or amount <= 0:
            return {"error": "invalid_params"}

        # Authorization: caller must be authorized to transfer FROM the source account
        if not self._check_authorization(from_account, caller, "transfer"):
            return {"error": "unauthorized"}

        balance = self._state.balances.get(from_account, 0)
        if balance < amount:
            return {"error": "insufficient_balance"}

        self._state.balances[from_account] = balance - amount
        self._state.balances[to_account] = self._state.balances.get(to_account, 0) + amount
        return {"success": True, "new_balance": self._state.balances[from_account]}

    def _add_delegate(self, caller: str, params: dict) -> dict:
        delegate_id = params.get("delegate_id")
        target_account = params.get("account", caller)

        if not delegate_id:
            return {"error": "invalid_params"}

        # Only the account owner can add delegates to their own account
        if target_account != caller:
            return {"error": "unauthorized"}

        if target_account not in self._state.delegates:
            self._state.delegates[target_account] = []

        if delegate_id not in self._state.delegates[target_account]:
            self._state.delegates[target_account].append(delegate_id)

        return {"success": True}

    def _get_balance(self, caller: str, params: dict) -> dict:
        account = params.get("account", caller)

        if not self._check_authorization(account, caller, "balance"):
            return {"error": "unauthorized"}

        return {"balance": self._state.balances.get(account, 0)}

    def _withdraw(self, caller: str, params: dict) -> dict:
        amount = params.get("amount", 0)
        source = params.get("account", caller)

        if amount <= 0:
            return {"error": "invalid_amount"}

        # Check caller is authorized for this account
        if not self._check_authorization(source, caller, "withdraw"):
            return {"error": "unauthorized"}

        balance = self._state.balances.get(source, 0)
        if balance < amount:
            return {"error": "insufficient_balance"}

        self._state.balances[source] = balance - amount
        return {"success": True, "withdrawn": amount}


# Service initialization
def create_contract_service(secret: bytes) -> SmartContract:
    auth = ServiceAuthenticator(secret)
    contract = SmartContract(auth)
    # Initialize some test accounts
    contract._state.balances = {
        "alice": 1000,
        "bob": 500,
        "charlie": 750
    }
    return contract
